// base64 → bajty. Deno i prohlížeč mají atob; Buffer tu není.
export function bajty(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
